import {choiceKey,validateChoices} from './option-choice-model.mjs';
import {buildOptionPlan,staffingSummary} from './option-planning.mjs';
export function createOptionChoicesUI({e,actor,toast,importPlanning}){
 let data,studentId='',draft=[],token=0,preview=null;
 const own=id=>data.records[id],isStudent=()=>actor()?.role==='student';
 async function api(body){const r=await fetch('/api/classroom/option-choices',{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error);return d;}
 function page(){const n=++token;queueMicrotask(async()=>{try{const d=await api();if(n!==token||!document.querySelector('#options-root'))return;data=d;if(!data.pupils.some(p=>p.id===studentId))studentId=isStudent()?actor().id:'';loadDraft();paint();}catch(err){if(n===token&&document.querySelector('#options-root'))document.querySelector('#options-root').textContent=err.message;}});return '<section class="vle"><div class="learning-section-title"><h1>Year 10 option choices</h1><span>TT Model 3 · 2026–27</span></div><div id="options-root">Opening the choice form…</div></section>';}
 function loadDraft(){draft=data.blocks.map((b,i)=>own(studentId)?.choices[i]||(b.choices.length===1?b.choices[0].subject:''));}
 function paint(){const root=document.querySelector('#options-root');if(!root)return;const pupil=data.pupils.find(p=>p.id===studentId);root.innerHTML='<div class="support-toolbar"><span>'+data.submitted+' / '+data.cohortSize+' students submitted · four lessons per subject · maximum 24 per class</span><button class="btn" data-options-refresh>Refresh counts</button>'+(data.manager?'<button class="btn" data-options-preview>Preview blocking</button><button class="btn" data-options-continuation>Year 11 continuation</button>':'')+'</div><p class="vle-note">Choose one subject in every block, including at least one science. A subject cannot be selected twice. Counts show saved submissions; places are checked again when you submit. Compulsory and language subjects use parallel classes of up to 24.</p><form data-option-form><label class="field"><span>1. Choose your name</span><select name="studentId" required '+(isStudent()?'disabled':'')+'><option value="">Choose a Year 10 student…</option>'+data.pupils.map(p=>'<option value="'+e(p.id)+'" '+(p.id===studentId?'selected':'')+'>'+e(p.name)+' · '+e(p.groupName)+(own(p.id)?' · submitted':'')+'</option>').join('')+'</select></label>'+(pupil?'<div class="option-form-grid">'+data.blocks.map((b,i)=>'<label class="field"><span>'+e(b.label)+(b.choices.some(c=>c.science)?' · science available':'')+'</span><select data-option-index="'+i+'" required><option value="">Choose a subject…</option>'+b.choices.map(c=>option(c,i)).join('')+'</select></label>').join('')+'</div><label class="option-declaration"><input type="checkbox" name="nonUzbek" '+(own(studentId)?.nonUzbek?'checked':'')+'> I am eligible for the alternatives marked ** (not from Uzbekistan, as specified on the option sheet).</label><p data-options-science></p><p class="error" role="alert" data-options-error></p><div class="actions"><button class="btn primary" type="submit">'+(own(studentId)?'Update submitted choices':'Submit choices')+'</button><span>'+e(pupil.name)+(own(studentId)?' · saved '+e(new Date(own(studentId).submittedAt).toLocaleString('en-GB',{timeZone:'Asia/Tashkent'})):' · not yet submitted')+'</span></div>':'<p>Select a name to open the option blocks.</p>')+'</form><div id="option-blocking-preview"></div><p class="muted"><small>Source: '+e(data.source)+' · This demonstration saves in this browser. Submitted choices do not change the active MIS timetable.</small></p>';bind(root);updateState();if(preview)paintPreview();}
 function option(c,i){const count=data.counts[choiceKey(i,c.subject)]||0,cap=data.blocks[i].sections*24,selected=draft[i]===c.subject,duplicate=draft.some((s,n)=>n!==i&&s===c.subject),full=count-(own(studentId)?.choices[i]===c.subject?1:0)>=cap;return '<option value="'+e(c.subject)+'" '+(selected?'selected':'')+' '+(!selected&&(duplicate||full)?'disabled':'')+'>'+e(c.subject)+(c.science?' [Science]':'')+(c.nonUzbekOnly?' **':'')+' · '+count+' chosen / '+cap+' places'+(duplicate?' · already selected':full?' · full':'')+'</option>';}
 function updateState(){const form=document.querySelector('[data-option-form]');if(!form||!studentId)return;form.querySelectorAll('[data-option-index]').forEach(s=>{const i=Number(s.dataset.optionIndex),value=draft[i];s.innerHTML='<option value="">Choose a subject…</option>'+data.blocks[i].choices.map(c=>option(c,i)).join('');s.value=value;});const science=draft.some(s=>['Physics','Chemistry','Biology'].includes(s));form.querySelector('[data-options-science]').textContent=science?'✓ At least one science selected.':'Select at least one science: Physics, Chemistry or Biology.';}
 function bind(root){const form=root.querySelector('[data-option-form]');form.elements.studentId.onchange=ev=>{studentId=ev.target.value;loadDraft();paint();};form.querySelectorAll('[data-option-index]').forEach(s=>s.onchange=ev=>{draft[Number(s.dataset.optionIndex)]=ev.target.value;updateState();});form.onsubmit=async ev=>{ev.preventDefault();const error=form.querySelector('[data-options-error]'),b=form.querySelector('[type=submit]');if(!studentId)return;b.disabled=true;try{validateChoices({choices:draft,records:data.records,studentId,cohortSize:data.cohortSize});await api({studentId,choices:draft,nonUzbek:form.elements.nonUzbek.checked,expectedRevision:own(studentId)?.revision||0});data=await api();loadDraft();preview=null;paint();toast('Option choices submitted. Counts have been updated.');}catch(err){error.textContent=err.message;b.disabled=false;}};root.querySelector('[data-options-refresh]').onclick=async()=>{try{const fresh=await api();data=fresh;updateState();toast('Latest submitted counts loaded.');}catch(err){toast(err.message);}};root.querySelector('[data-options-preview]')?.addEventListener('click',()=>makePreview(false));root.querySelector('[data-options-continuation]')?.addEventListener('click',()=>makePreview(true));}
 async function makePreview(continuation){try{const r=await fetch('timetable-integrated.json',{cache:'no-store'});if(!r.ok)throw Error('Could not load the timetable planning template.');const base=await r.json();data=await api();preview=buildOptionPlan(base,data,{continuation});paintPreview();}catch(err){toast(err.message);}}
 function paintPreview(){const root=document.querySelector('#option-blocking-preview');if(!root||!preview)return;const p=preview;root.innerHTML='<section class="vle-panel"><div class="learning-section-title"><h2>'+e(p.name)+'</h2><button class="btn primary" data-options-import>Open this planning draft</button></div><p>'+p.optionCollection.submitted+' / '+p.optionCollection.total+' submitted students. '+(p.optionCollection.submitted<p.optionCollection.total?'Partial preview — outstanding students must submit before this is a complete cohort timetable.':'All cohort choices received.')+' Year 11 continuation keeps the same student IDs, block choices and four periods per subject.</p><div class="table-wrap support-scroll"><table class="data-table"><thead><tr><th>Block</th><th>Subject / class</th><th>Students</th><th>Periods</th><th>Teacher</th></tr></thead><tbody>'+p.activities.filter(a=>a.blockId).map(a=>'<tr><td>'+e(p.optionBlocks.find(b=>b.id===a.blockId)?.name)+'</td><td>'+e(a.name)+'</td><td>'+a.studentIds.length+' / 24'+(a.supportReservation?' · reserved support':'')+'</td><td>'+a.weeklyCount*a.duration+'</td><td>'+e(p.teachers.find(t=>t.id===a.teacherIds[0])?.name)+'</td></tr>').join('')+'</tbody></table></div><details><summary>Staffing and year-level spread</summary>'+staffingSummary(p).map(t=>'<p>'+e(t.name)+' · '+e(t.duty)+' · '+t.load+' / '+t.limit+' ('+t.inDraft+' in this draft + '+t.committed+' other-year periods) · Years '+e(t.years.join(', '))+'</p>').join('')+'</details><p>'+e(p.staffingReview.message)+(p.staffingReview.unassigned.length?' '+e(p.staffingReview.unassigned.join('; '))+' Open the planning draft, then People & rooms to add a specialist or Teaching loads to revise allocations.':'')+'</p><p>Teacher totals include existing other-year commitments for the Year 10 draft. The Year 11 continuation is a future-year scenario requiring a fresh staffing review.</p></section>';root.querySelector('[data-options-import]').onclick=()=>{try{importPlanning(p);location.hash='/timetable?tab=options';toast('Model 3 planning draft opened. The active MIS timetable is unchanged.');}catch(err){toast(err.message);}};}
 return{page};
}
